import type { UserSetting_TagMetadata, UserSetting_TagsSetting } from "@/types/proto/api/user_service_pb";

// Cache compiled regexes to avoid re-compiling on every tag render.
const compiledPatternCache = new Map<string, RegExp | null>();

/** Merge exact tag counts without inheriting Object prototype keys. */
export const mergeTagCounts = (...sources: Array<Record<string, number> | undefined>): Record<string, number> => {
  const result = Object.create(null) as Record<string, number>;
  for (const source of sources) {
    for (const [tag, count] of Object.entries(source ?? {})) result[tag] = (result[tag] ?? 0) + count;
  }
  return result;
};

const getCompiledPattern = (pattern: string): RegExp | null => {
  if (compiledPatternCache.has(pattern)) {
    return compiledPatternCache.get(pattern)!;
  }
  let re: RegExp | null = null;
  try {
    re = new RegExp(`^(?:${pattern})$`);
  } catch {
    // Invalid pattern — cache as null so we skip it without retrying.
  }
  compiledPatternCache.set(pattern, re);
  return re;
};

/**
 * Finds the first matching TagMetadata for a given tag name by treating each
 * key in tagsSetting.tags as an anchored regex pattern (^pattern$).
 *
 * Lookup order:
 * 1. Exact key match (O(1) fast path, backward-compatible).
 * 2. Iterate all keys and test as anchored regex — first match wins.
 */
export const findTagMetadata = (tag: string, tagsSetting: UserSetting_TagsSetting): UserSetting_TagMetadata | undefined => {
  // Fast path: exact match.
  if (Object.hasOwn(tagsSetting.tags, tag)) {
    return tagsSetting.tags[tag];
  }

  // Regex path: treat each key as an anchored pattern.
  for (const [pattern, metadata] of Object.entries(tagsSetting.tags)) {
    const re = getCompiledPattern(pattern);
    if (re?.test(tag)) {
      return metadata;
    }
  }

  return undefined;
};

/**
 * Returns true if the given string is a valid, ReDoS-safe JavaScript regex pattern.
 *
 * Rejects patterns with nested quantifiers (e.g. `(a+)+`) which can cause
 * catastrophic backtracking in JavaScript's regex engine.
 */
export const isValidTagPattern = (pattern: string): boolean => {
  if (!pattern) return false;
  try {
    new RegExp(pattern);
  } catch {
    return false;
  }
  // Reject nested quantifiers: a quantified group whose body itself contains
  // a quantifier — the classic ReDoS shape e.g. (a+)+, (a*b?)+, (x|y+)+.
  if (/\((?:[^()]*[*+?{][^()]*)\)[*+?{]/.test(pattern)) {
    return false;
  }
  return true;
};

/** Whether any of the memo's tags is set to blur its content for this user. */
export const isMemoBlurred = (memo: { tags: string[] }, tagsSetting: UserSetting_TagsSetting | undefined): boolean =>
  tagsSetting !== undefined && memo.tags.some((tag) => findTagMetadata(tag, tagsSetting)?.blurContent === true);
import { create, fromBinary, toBinary } from "@bufbuild/protobuf";
import { describe, expect, it } from "vitest";
import { findTagMetadata, mergeTagCounts } from "@/lib/tag";
import { UserSetting_TagMetadataSchema, UserSetting_TagsSettingSchema, UserStatsSchema } from "@/types/proto/api/user_service_pb";

describe("exact tag keys", () => {
  it("aggregates names that collide with Object prototype properties", () => {
    const source = Object.fromEntries([
      ["toString", 1],
      ["constructor", 2],
      ["__proto__", 3],
    ]);
    const counts = mergeTagCounts(source, { toString: 4 });

    expect(Object.getPrototypeOf(counts)).toBeNull();
    expect(counts.toString).toBe(5);
    expect(counts.constructor).toBe(2);
    expect(counts.__proto__).toBe(3);
  });

  it("preserves exact prototype-shaped tag keys through protobuf maps", () => {
    const source = Object.fromEntries([
      ["normal", 1],
      ["constructor", 2],
      ["__proto__", 3],
    ]);
    const encoded = toBinary(UserStatsSchema, create(UserStatsSchema, { tagCounts: source }));
    const decoded = fromBinary(UserStatsSchema, encoded);
    const counts = mergeTagCounts(decoded.tagCounts);

    expect(Object.keys(decoded.tagCounts).sort()).toEqual(["__proto__", "constructor", "normal"]);
    expect(counts.normal).toBe(1);
    expect(counts.constructor).toBe(2);
    expect(counts.__proto__).toBe(3);
  });

  it("preserves exact prototype-shaped metadata keys when creating tag settings", () => {
    const source = Object.fromEntries([
      ["normal", { blurContent: false }],
      ["constructor", { blurContent: true }],
      ["__proto__", { blurContent: true }],
    ]);
    const created = create(UserSetting_TagsSettingSchema, { tags: source });
    const decoded = fromBinary(UserSetting_TagsSettingSchema, toBinary(UserSetting_TagsSettingSchema, created));

    expect(Object.keys(created.tags).sort()).toEqual(["__proto__", "constructor", "normal"]);
    expect(Object.keys(decoded.tags).sort()).toEqual(["__proto__", "constructor", "normal"]);
    expect(decoded.tags.normal.blurContent).toBe(false);
    expect(decoded.tags["constructor"].blurContent).toBe(true);
    expect(decoded.tags.__proto__.blurContent).toBe(true);
  });

  it("does not treat inherited properties as exact metadata", () => {
    const metadata = create(UserSetting_TagMetadataSchema, { blurContent: true });
    const setting = create(UserSetting_TagsSettingSchema, { tags: { ".*": metadata } });

    expect(findTagMetadata("toString", setting)).toBe(metadata);
  });
});
